// ─────────────────────────────────────────────────────────────
// OCR 100% FRONTEND — Tesseract.js con Canvas preprocesado
// Escanea franjas de la imagen con binarización para leer
// montos de comprobantes Bancolombia/Nequi/Daviplata/Bre-B
// ─────────────────────────────────────────────────────────────

let _tesseractWorker = null;

const obtenerWorker = async () => {
  if (_tesseractWorker) return _tesseractWorker;
  await new Promise((resolve, reject) => {
    if (window.Tesseract) { resolve(); return; }
    const s = document.createElement("script");
    s.src = "https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js";
    s.onload  = resolve;
    s.onerror = () => reject(new Error("No se pudo cargar OCR"));
    document.head.appendChild(s);
  });
  // PSM 6 = bloque uniforme (mejor para comprobantes)
  _tesseractWorker = await window.Tesseract.createWorker("eng", 1, { logger: () => {} });
  await _tesseractWorker.setParameters({ tessedit_pageseg_mode: "6" });
  return _tesseractWorker;
};

// Recorta una franja de la imagen, la binariza y devuelve Blob PNG
const preprocesarFranja = (imgEl, yStart, yEnd) =>
  new Promise(resolve => {
    const W = imgEl.naturalWidth;
    const H = yEnd - yStart;
    const SCALE = 3;
    const c = document.createElement("canvas");
    c.width  = W * SCALE;
    c.height = H * SCALE;
    const ctx = c.getContext("2d");
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, c.width, c.height);
    ctx.drawImage(imgEl, 0, yStart, W, H, 0, 0, c.width, c.height);
    // Binarizar: texto oscuro → negro, fondo claro → blanco
    const id = ctx.getImageData(0, 0, c.width, c.height);
    const d  = id.data;
    for (let i = 0; i < d.length; i += 4) {
      const g = 0.299*d[i] + 0.587*d[i+1] + 0.114*d[i+2];
      const v = g < 160 ? 0 : 255;
      d[i] = d[i+1] = d[i+2] = v; d[i+3] = 255;
    }
    ctx.putImageData(id, 0, 0);
    c.toBlob(resolve, "image/png");
  });

// Normaliza string de monto colombiano a entero
// "$99.000,00" | "99.000" | "$99" | "99000" → entero
const normalizarMonto = (raw) => {
  let s = String(raw).trim();
  s = s.replace(/[.,]\d{2}$/, "");  // quitar centavos ,00
  s = s.replace(/\s/g, "");          // quitar espacios internos ("1 00" → "100")
  s = s.replace(/[^0-9]/g, "");       // solo dígitos
  const n = parseInt(s, 10);
  return isNaN(n) || n <= 0 ? -1 : n;
};

// Extrae monto de texto OCR — patrones banco colombiano
const extraerMonto = (texto) => {
  if (!texto) return -1;
  let t = texto.replace(/\r?\n/g, " ").replace(/\s+/g, " ");
  // Unir dígitos separados por espacios (artefacto OCR: "1 0 0" → "100")
  // Doble pasada para cubrir más de un espacio
  t = t.replace(/(\d)\s+(\d)/g, "$1$2").replace(/(\d)\s+(\d)/g, "$1$2");
  // "$ 100" → "$100"
  t = t.replace(/\$\s+/g, "$");
  // "S 100" o "S100" → "$100"  (OCR confunde $ con S)
  t = t.replace(/\bS\s*(\d)/g, "$$$1");

  const patrones = [
    /valor\s+del\s+pago\s*[$S]?\s*([\d][0-9.,\s]*)/i,   // Bre-B
    /valor\s*transferido\s*[$S]?\s*([\d][0-9.,\s]*)/i,    // Bancolombia
    /transferiste\s*[$S]?\s*([\d][0-9.,\s]*)/i,            // Nequi
    /transferencia\s*(?:por|de)?\s*[$S]?\s*([\d][0-9.,\s]*)/i,
    /pagaste\s*[$S]?\s*([\d][0-9.,\s]*)/i,                 // Daviplata
    /(?:monto|total|amount)\s*:?\s*[$S]?\s*([\d][0-9.,\s]*)/i,
    /pago\s+exitoso[^$\d]{0,60}[$S]\s*([\d][0-9.,\s]*)/i, // Bre-B fallback
    /(?:valor|pago)[^$\d]{0,30}[$S]\s*([\d][0-9.,\s]*)/i,
  ];

  for (const re of patrones) {
    const m = t.match(re);
    if (m) { const v = normalizarMonto(m[1]); if (v > 0 && v <= 50_000_000) return v; }
  }

  // Fallback: $ o S seguido de dígitos
  const todos = [...t.matchAll(/[$S](\d[0-9.,\s]*)/g)]
    .map(m => normalizarMonto(m[1]))
    .filter(v => v > 0 && v <= 50_000_000);

  if (todos.length) return Math.max(...todos);
  return -1;
};

// Carga archivo como HTMLImageElement
const cargarImagen = (file) =>
  new Promise((res, rej) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload  = () => { URL.revokeObjectURL(url); res(img); };
    img.onerror = () => { URL.revokeObjectURL(url); rej(new Error("Imagen inválida")); };
    img.src = url;
  });

// Función principal: escanea 8 franjas solapadas → extrae monto
const extractReceiptData = async (file) => {
  const worker = await obtenerWorker();
  const imgEl  = await cargarImagen(file);
  const H      = imgEl.naturalHeight;

  // Franjas: paso 8%, alto 12% — franjas pequeñas que capturan
  // el monto sin incluir líneas vecinas que confunden el OCR
  const paso = Math.floor(H * 0.08);
  const alto = Math.floor(H * 0.12);
  const franjas = [];
  for (let y = 0; y + alto <= H; y += paso) franjas.push(y);
  if (franjas[franjas.length-1] + alto < H) franjas.push(H - alto);

  let montoFinal = -1;
  let textoTotal = "";

  for (const y of franjas) {
    const yEnd = Math.min(y + alto, H);
    const blob = await preprocesarFranja(imgEl, y, yEnd);
    const { data } = await worker.recognize(blob);
    const txt = data.text || "";
    textoTotal += " " + txt;
    // Detener en cuanto encontremos un monto válido
    if (montoFinal === -1) {
      const m = extraerMonto(txt);
      if (m > 0) montoFinal = m;
    }
  }

  // Último intento con texto completo combinado
  if (montoFinal === -1) montoFinal = extraerMonto(textoTotal);

  return { monto: montoFinal, confianza: montoFinal > 0 ? 90 : 0 };
};

// ─────────────────────────────────────────────────────────────
// PAYMENT MODAL (integrado, sin <style>, sin HTML)
// ─────────────────────────────────────────────────────────────
const PaymentModalInner = ({ isOpen, onClose, onPedidoCreado, items=[], total=0, metodoEntrega, direccion, user }) => {
  const fileRef    = useRef(null);
  const esTienda   = metodoEntrega === "tienda";
  const stepInicial = esTienda ? "confirmar-tienda" : "qr";

  const [step,       setStep]       = useState(stepInicial);
  const [archivo,    setArchivo]    = useState(null);
  const [preview,    setPreview]    = useState(null);
  const [progreso,   setProgreso]   = useState(0);
  const [errorMsg,   setErrorMsg]   = useState("");
  const [pedidoId,   setPedidoId]   = useState(null);
  const [isDragging, setIsDragging] = useState(false);
  const [ocrData,    setOcrData]    = useState(null);

  useEffect(() => {
    setStep(stepInicial); setArchivo(null); setPreview(null);
    setProgreso(0); setErrorMsg(""); setPedidoId(null);
    setIsDragging(false); setOcrData(null);
  }, [metodoEntrega, isOpen]); // eslint-disable-line

  const reset      = () => { setStep(stepInicial); setArchivo(null); setPreview(null); setProgreso(0); setErrorMsg(""); setPedidoId(null); setIsDragging(false); setOcrData(null); };
  const handleClose = () => { reset(); onClose(); };

  const TIPOS_IMG = ["image/jpeg","image/png","image/webp","image/gif"];
  const TIPOS_OK  = [...TIPOS_IMG,"application/pdf"];

  // ── Procesar archivo + OCR ─────────────────────────────────
  const procesarArchivo = async (file) => {
    if (!file) return;
    if (!TIPOS_OK.includes(file.type)) { setErrorMsg("Solo JPG, PNG, WEBP o PDF (máx 10 MB)."); return; }
    if (file.size > 10*1024*1024)       { setErrorMsg("El archivo supera los 10 MB."); return; }

    setErrorMsg(""); setOcrData(null); setArchivo(file);

    if (file.type.startsWith("image/")) {
      const reader = new FileReader();
      reader.onload = e => setPreview({ tipo:"img", url:e.target.result, nombre:file.name });
      reader.readAsDataURL(file);
    } else {
      setPreview({ tipo:"pdf", nombre:file.name });
    }

    if (TIPOS_IMG.includes(file.type)) {
      setStep("verificando");
      try {
        const datos = await extractReceiptData(file);
        setOcrData(datos);

        const esperado = Math.round(total);

        if (datos.monto === -1 || datos.confianza < 10) {
          setErrorMsg(
            "No pudimos leer el monto del comprobante. Asegúrate de que la imagen sea nítida, bien iluminada y muestre el valor transferido claramente."
          );
          setStep("upload"); return;
        }

        if (datos.monto !== esperado) {
          setErrorMsg(
            datos.monto < esperado
              ? `Fondos insuficientes: el comprobante muestra ${fmt(datos.monto)} pero se requieren exactamente ${fmt(esperado)}.`
              : `El comprobante muestra ${fmt(datos.monto)}, pero el total es ${fmt(esperado)}. El monto debe ser exacto.`
          );
          setStep("upload"); return;
        }
        // ✅ Monto correcto
        setStep("upload");
      } catch (err) {
        setErrorMsg(err?.message || "No se pudo verificar el comprobante. Intenta con una imagen más clara.");
        setStep("upload");
      }
    } else {
      // PDF — pasa directo sin OCR
      setStep("upload");
    }
  };

  const onFileChange = e => procesarArchivo(e.target.files[0]);
  const onDrop       = e => { e.preventDefault(); setIsDragging(false); procesarArchivo(e.dataTransfer.files[0]); };
  const onDragOver   = e => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave  = () => setIsDragging(false);

  const obtenerClienteId = async (token) => {
    let cid = user?.cliente_id ?? user?.clienteId ?? null;
    if (!cid) {
      try {
        const r = await fetch(`${BASE_URL}/cliente/perfil`, { headers:{ Authorization:`Bearer ${token}` } });
        if (r.ok) { const p = await r.json(); cid = p.id ?? p.cliente_id ?? null; }
      } catch {}
    }
    return cid;
  };

  const subirComprobante = async () => {
    if (!archivo) return;
    setStep("subiendo"); setProgreso(0);
    try {
      const form = new FormData();
      form.append("file", archivo);
      form.append("upload_preset", UPLOAD_PRESET);
      form.append("folder", "optica/comprobantes");
      const xhr = new XMLHttpRequest();
      xhr.upload.onprogress = e => { if (e.lengthComputable) setProgreso(Math.round((e.loaded/e.total)*85)); };
      const data = await new Promise((res,rej) => {
        xhr.onload  = () => xhr.status===200 ? res(JSON.parse(xhr.responseText)) : rej();
        xhr.onerror = () => rej();
        xhr.open("POST", `https://api.cloudinary.com/v1_1/${CLOUD_NAME}/auto/upload`);
        xhr.send(form);
      });
      setProgreso(100);
      await crearPedido(data.secure_url);
    } catch { setErrorMsg("No se pudo subir el comprobante. Verifica tu conexión."); setStep("upload"); }
  };

  const crearPedido = async (urlComprobante = "") => {
    setStep("confirmando");
    const token = getToken();
    if (!token) { setErrorMsg("Sesión expirada. Inicia sesión."); setStep("error"); return; }

    const clienteId = await obtenerClienteId(token);
    if (!clienteId) { setErrorMsg("No encontramos tu perfil. Inicia sesión de nuevo."); setStep("error"); return; }

    try {
      // Conecta directo a POST /ventas — registra la venta en el sistema
      const payload = {
        cliente_id:                clienteId,
        metodo_pago:               esTienda ? "efectivo" : "transferencia",
        metodo_entrega:            metodoEntrega || "tienda",
        direccion_entrega:         metodoEntrega === "domicilio" ? direccion : "",
        transferencia_comprobante: urlComprobante || null,
        items: items.map(i => ({
          producto_id:     i.id,
          cantidad:        i.cantidad,
          precio_unitario: i.precioVenta,
          descuento:       0,
        })),
      };

      const r = await fetch(`${BASE_URL}/ventas`, {
        method:  "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body:    JSON.stringify(payload),
      });

      const d = await r.json();

      if (!r.ok) {
        setErrorMsg(d.error || "No se pudo registrar la venta.");
        setStep("error");
        return;
      }

      // La API devuelve { message, venta: { id, ... } }
      setPedidoId(d.venta?.id || "");
      setStep("exito");
      if (onPedidoCreado) onPedidoCreado(d.venta?.id);

    } catch {
      setErrorMsg("Error de conexión al registrar la venta.");
      setStep("error");
    }
  };

  if (!isOpen) return null;

  const montoOK        = ocrData && ocrData.monto !== -1 && ocrData.monto === Math.round(total);
  const puedeConfirmar = montoOK || (archivo && preview?.tipo === "pdf" && !errorMsg);

  const IconArrow = () => (
    <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" width="16" height="16">
      <path d="M5 10h10M12 7l3 3-3 3"/>
    </svg>
  );

  return (
    <>
      <div className="pm-backdrop" onClick={handleClose} />
      <div className="pm-drawer pm-drawer--open" role="dialog" aria-label="Pago">

        <div className="pm-header">
          <div>
            <p className="pm-header-title">{esTienda ? "Retirar en tienda" : "Pago por transferencia"}</p>
            <p className="pm-header-sub">{esTienda ? "Pago en efectivo al retirar" : "Bancolombia · Nequi · Daviplata"}</p>
          </div>
          <button className="pm-close" onClick={handleClose}>×</button>
        </div>

        <div className="pm-total-strip">
          <span className="pm-total-label">{esTienda ? "TOTAL A PAGAR EN TIENDA" : "TOTAL A TRANSFERIR"}</span>
          <span className="pm-total-value">{fmt(total)}</span>
        </div>

        <div className="pm-body">

          {/* TIENDA */}
          {step === "confirmar-tienda" && (
            <>
              <div className="pm-tienda-icon">
                <svg viewBox="0 0 64 64" fill="none" stroke="#6aaeae" strokeWidth="1.5">
                  <path d="M8 28v28h48V28"/><path d="M2 28h60M20 56V36h24v20"/>
                  <path d="M4 14l6-12h44l6 12"/>
                  <path d="M4 14c0 5.52 3.58 10 8 10s8-4.48 8-10M20 14c0 5.52 3.58 10 8 10s8-4.48 8-10M36 14c0 5.52 3.58 10 8 10s8-4.48 8-10"/>
                </svg>
              </div>
              <div className="pm-instruccion">
                <div className="pm-instruccion-num">📍</div>
                <div>
                  <p className="pm-instruccion-titulo">Cómo funciona</p>
                  <p className="pm-instruccion-sub">Reservamos tus productos. Retíralos y paga en efectivo en nuestra tienda.</p>
                </div>
              </div>
              <div className="pm-resumen">
                <p className="pm-resumen__titulo">Resumen del pedido</p>
                {items.map(it => (
                  <div key={it.id} className="pm-resumen__row">
                    <span className="pm-resumen__name">{it.nombre} ×{it.cantidad}</span>
                    <span className="pm-resumen__price">{fmt(it.precioVenta*it.cantidad)}</span>
                  </div>
                ))}
                <div className="pm-resumen__total"><span>Total a pagar</span><span>{fmt(total)}</span></div>
              </div>
            </>
          )}

          {/* QR */}
          {step === "qr" && (
            <>
              <div className="pm-qr-card">
                <img src={QR_DATA_URL} alt="QR Bancolombia" className="pm-qr-img" />
                <div className="pm-qr-divider" />
                <p className="pm-qr-llave">@camacho5281</p>
                <p className="pm-qr-hint">Escanea con Bancolombia, Nequi, Daviplata o cualquier app bancaria</p>
              </div>
              <div className="pm-instruccion">
                <div className="pm-instruccion-num">2</div>
                <div>
                  <p className="pm-instruccion-titulo">Transfiere exactamente</p>
                  <p className="pm-instruccion-monto">{fmt(total)}</p>
                </div>
              </div>
              <div
                className={`pm-upload-zone${isDragging?" pm-upload-zone--drag":""}`}
                onClick={() => fileRef.current?.click()}
                onDrop={onDrop} onDragOver={onDragOver} onDragLeave={onDragLeave}
                role="button" tabIndex={0}
              >
                <svg className="pm-upload-zone__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                  <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/>
                  <polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/>
                </svg>
                <span className="pm-upload-zone__label">Subir comprobante de pago</span>
                <span className="pm-upload-zone__hint">JPG · PNG · PDF · máx 10 MB</span>
                <input ref={fileRef} type="file" accept="image/*,application/pdf" onChange={onFileChange} className="pm-file-input" />
              </div>
              {errorMsg && <p className="pm-error-box">{errorMsg}</p>}
            </>
          )}

          {/* VERIFICANDO */}
          {step === "verificando" && (
            <div className="pm-center">
              <div className="pm-spinner" />
              <p className="pm-center__title">Verificando comprobante…</p>
              <p className="pm-center__sub">La IA está leyendo el monto del comprobante</p>
            </div>
          )}

          {/* UPLOAD */}
          {step === "upload" && (
            <>
              {montoOK && !errorMsg && (
                <div className="pm-ocr-ok">
                  <svg className="pm-ocr-ok__icon" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" width="16" height="16">
                    <polyline points="4 10 8 14 16 6"/>
                  </svg>
                  <div>
                    <p className="pm-ocr-ok__titulo">Monto verificado correctamente</p>
                    <p className="pm-ocr-ok__sub">{fmt(ocrData.monto)}{ocrData.remitente ? ` · Enviado por: ${ocrData.remitente}` : ""}</p>
                  </div>
                </div>
              )}
              <div
                className="pm-preview"
                onClick={() => fileRef.current?.click()}
                onDrop={onDrop} onDragOver={onDragOver} onDragLeave={onDragLeave}
                role="button" tabIndex={0}
              >
                <div className="pm-preview__inner">
                  {preview?.tipo === "img"
                    ? <img src={preview.url} alt="Comprobante" className="pm-preview__thumb" />
                    : <div className="pm-preview__pdf-icon">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                          <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
                          <polyline points="14 2 14 8 20 8"/>
                        </svg>
                      </div>
                  }
                  <div className="pm-preview__meta">
                    <p className="pm-preview__name">{preview?.nombre}</p>
                    <p className="pm-preview__hint">Toca para cambiar</p>
                  </div>
                </div>
                <input ref={fileRef} type="file" accept="image/*,application/pdf" onChange={onFileChange} className="pm-file-input" />
              </div>
              <div className="pm-resumen">
                <p className="pm-resumen__titulo">Resumen del pedido</p>
                {items.map(it => (
                  <div key={it.id} className="pm-resumen__row">
                    <span className="pm-resumen__name">{it.nombre} ×{it.cantidad}</span>
                    <span className="pm-resumen__price">{fmt(it.precioVenta*it.cantidad)}</span>
                  </div>
                ))}
                <div className="pm-resumen__total"><span>Total</span><span>{fmt(total)}</span></div>
                {metodoEntrega === "domicilio" && direccion && (
                  <div className="pm-resumen__dir">
                    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" width="12" height="12">
                      <path d="M8 1C5.24 1 3 3.24 3 6c0 4 5 9 5 9s5-5 5-9c0-2.76-2.24-5-5-5z"/>
                      <circle cx="8" cy="6" r="1.5"/>
                    </svg>
                    {direccion}
                  </div>
                )}
              </div>
              {errorMsg && <p className="pm-error-box">{errorMsg}</p>}
            </>
          )}

          {/* SUBIENDO */}
          {step === "subiendo" && (
            <div className="pm-center">
              <div className="pm-upload-anim">
                <svg viewBox="0 0 48 48" fill="none" stroke="currentColor" strokeWidth="1.5">
                  <path d="M24 32V16M17 23l7-7 7 7"/>
                  <path d="M8 36a8 8 0 010-16h2M40 36a8 8 0 000-16h-2"/>
                </svg>
              </div>
              <p className="pm-center__title">Subiendo comprobante…</p>
              <div className="pm-progress">
                <div className="pm-progress__track">
                  <div className="pm-progress__fill" style={{ width:`${progreso}%` }} />
                </div>
                <span className="pm-progress__pct">{progreso}%</span>
              </div>
            </div>
          )}

          {/* CONFIRMANDO */}
          {step === "confirmando" && (
            <div className="pm-center">
              <div className="pm-spinner" />
              <p className="pm-center__title">Registrando tu pedido…</p>
              <p className="pm-center__sub">Un momento por favor</p>
            </div>
          )}

          {/* ÉXITO */}
          {step === "exito" && (
            <div className="pm-center">
              <div className="pm-success__icon">
                <svg viewBox="0 0 56 56" fill="none">
                  <circle cx="28" cy="28" r="26" fill="rgba(61,128,128,0.15)" stroke="#3d8080" strokeWidth="1.5"/>
                  <polyline points="17 29 24 36 39 21" stroke="#6aaeae" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              </div>
              <p className="pm-success__title">¡Pedido registrado!</p>
              {pedidoId && <p className="pm-center__sub">Pedido #{pedidoId}</p>}
              <p className="pm-success__msg">
                {esTienda
                  ? "Tu pedido fue reservado. Pasa por la tienda para retirarlo y pagar en efectivo."
                  : "Tu comprobante fue verificado y el pedido registrado exitosamente."}
              </p>
              <button className="pm-btn-primary" onClick={handleClose}>Listo, cerrar</button>
            </div>
          )}

          {/* ERROR */}
          {step === "error" && (
            <div className="pm-center">
              <div className="pm-error-icon">
                <svg viewBox="0 0 56 56" fill="none">
                  <circle cx="28" cy="28" r="26" stroke="#fca5a5" strokeWidth="1.5"/>
                  <line x1="28" y1="18" x2="28" y2="30" stroke="#fca5a5" strokeWidth="2" strokeLinecap="round"/>
                  <circle cx="28" cy="38" r="1.5" fill="#fca5a5"/>
                </svg>
              </div>
              <p className="pm-center__title">Algo salió mal</p>
              <p className="pm-error-box">{errorMsg}</p>
              <button className="pm-btn-ghost" onClick={() => { setStep(stepInicial); setErrorMsg(""); }}>Intentar de nuevo</button>
            </div>
          )}

        </div>

        <div className="pm-footer">
          {step === "confirmar-tienda" && (
            <>
              <button className="pm-btn-primary" onClick={() => crearPedido("")}>
                Confirmar reserva <IconArrow />
              </button>
              <p className="pm-footer__security">🏪 Pagas en efectivo cuando retires en tienda</p>
            </>
          )}
          {step === "qr" && <p className="pm-footer__security">🔒 Pago seguro — transferencia directa bancaria</p>}
          {step === "upload" && puedeConfirmar && (
            <button className="pm-btn-primary" onClick={subirComprobante}>Confirmar pago <IconArrow /></button>
          )}
          {step === "upload" && errorMsg && (
            <button className="pm-btn-ghost" onClick={() => { setErrorMsg(""); setOcrData(null); fileRef.current?.click(); }}>
              Subir otro comprobante
            </button>
          )}
          {(step==="subiendo"||step==="confirmando"||step==="verificando") && (
            <button className="pm-btn-primary" disabled><span className="pm-spinner-sm" /> Procesando…</button>
          )}
        </div>

      </div>
    </>
  );
};

// ─────────────────────────────────────────────────────────────
// CONTEXT
// ─────────────────────────────────────────────────────────────
const CartContext = createContext(null);
export const useCart = () => {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error("useCart debe usarse dentro de CartProvider");
  return ctx;
};

const getUid = (user) => user?.id ?? user?.cliente_id ?? user?.email ?? null;

export const CartProvider = ({ children, user }) => {
  const uid = getUid(user);

  const [items,    setItems]    = useState(() => loadLS(cartKey(uid)) || []);
  const [wishlist, setWishlist] = useState(() => loadLS(wishKey(uid)) || []);
  const [isOpen,   setIsOpen]   = useState(false);
  const [wishOpen, setWishOpen] = useState(false);
  const [pagoOpen, setPagoOpen] = useState(false);
  const [pedidoData, setPedidoData] = useState(null);

  useEffect(() => {
    setItems(loadLS(cartKey(uid)) || []);
    setWishlist(loadLS(wishKey(uid)) || []);
    setIsOpen(false); setWishOpen(false); setPagoOpen(false); setPedidoData(null);
  }, [uid]);

  useEffect(() => { saveLS(cartKey(uid), items); },    [items, uid]);
  useEffect(() => { saveLS(wishKey(uid), wishlist); }, [wishlist, uid]);

  const cartCount = items.reduce((s,i)=>s+i.cantidad,0);
  const cartTotal = items.reduce((s,i)=>s+i.precioVenta*i.cantidad,0);
  const wishCount = wishlist.length;

  const addToCart          = useCallback((prod) => {
    const { id,nombre,precioVenta,imagenPrincipal,imagenes,stockActual,cantidad=1 } = prod;
    setItems(prev => {
      const ex = prev.find(i=>i.id===id);
      if (ex) return prev.map(i=>i.id===id?{...i,cantidad:Math.min(i.cantidad+cantidad,stockActual)}:i);
      return [...prev,{id,nombre,precioVenta,imagenPrincipal,imagenes,stockActual,cantidad}];
    });
  },[]);

  const removeFromCart     = useCallback((id) => setItems(p=>p.filter(i=>i.id!==id)),[]);
  const updateQuantity     = useCallback((id,delta) => setItems(prev=>prev.map(item=>{
    if(item.id!==id) return item;
    const n=item.cantidad+delta;
    if(n<1||n>item.stockActual) return item;
    return {...item,cantidad:n};
  })),[]);
  const clearCart          = useCallback(()=>{ setItems([]); saveLS(cartKey(uid),[]); },[uid]);
  const toggleWishlist     = useCallback((prod)=>setWishlist(prev=>prev.find(i=>i.id===prod.id)?prev.filter(i=>i.id!==prod.id):[...prev,prod]),[]);
  const isInWishlist       = useCallback((id)=>wishlist.some(i=>i.id===id),[wishlist]);
  const removeFromWishlist = useCallback((id)=>setWishlist(p=>p.filter(i=>i.id!==id)),[]);
  const toggleCart         = useCallback(()=>setIsOpen(p=>!p),[]);
  const closeCart          = useCallback(()=>setIsOpen(false),[]);
  const openCart           = useCallback(()=>setIsOpen(true),[]);
  const openWishlist       = useCallback(()=>{ setWishOpen(true); setIsOpen(false); },[]);
  const closeWishlist      = useCallback(()=>setWishOpen(false),[]);
  const openPagoModal      = useCallback((data)=>{ setPedidoData(data); setPagoOpen(true); },[]);
  const closePagoModal     = useCallback(()=>{ setPagoOpen(false); setPedidoData(null); },[]);

  return (
    <CartContext.Provider value={{
      items,cartCount,cartTotal,isOpen,
      wishlist,wishCount,wishOpen,
      addToCart,removeFromCart,updateQuantity,clearCart,
      toggleWishlist,isInWishlist,removeFromWishlist,
      toggleCart,closeCart,openCart,openWishlist,closeWishlist,
      openPagoModal,closePagoModal,user,uid,
    }}>
      {children}
      {pagoOpen && pedidoData && (
        <PaymentModalInner
          isOpen={pagoOpen}
          onClose={closePagoModal}
          onPedidoCreado={(_id) => {
            const idsComprados = new Set(items.map(i=>i.id));
            setWishlist(prev => { const nueva=prev.filter(w=>!idsComprados.has(w.id)); saveLS(wishKey(uid),nueva); return nueva; });
            clearCart();
            closePagoModal();
          }}
          items={pedidoData.items}
          total={pedidoData.total}
          metodoEntrega={pedidoData.metodoEntrega}
          direccion={pedidoData.direccion}
          user={user}
        />
      )}
    </CartContext.Provider>
  );
};

// ─────────────────────────────────────────────────────────────
// DELIVERY FORM
// ─────────────────────────────────────────────────────────────
const DeliveryForm = ({ value, onChange, errors, uid }) => {
  const [geoLoading,   setGeoLoading]   = useState(false);
  const [geoError,     setGeoError]     = useState("");

  const ciudades = useMemo(() => value.departamento ? (COLOMBIA_GEO[value.departamento]||[]) : [], [value.departamento]);

  const handleDeptChange = (dept) => {
    const c = (COLOMBIA_GEO[dept]||[]).includes(value.ciudad) ? value.ciudad : "";
    onChange({ ...value, departamento:dept, ciudad:c });
  };

  const handleGeolocate = () => {
    if (!navigator.geolocation) { setGeoError("Tu navegador no soporta geolocalización."); return; }
    setGeoLoading(true); setGeoError("");
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        try {
          const { latitude, longitude } = pos.coords;
          const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&addressdetails=1&accept-language=es`, { headers:{ "User-Agent":"OpticaApp/1.0" } });
          const data = await res.json();
          const addr = data.address || {};
          const estadoRaw = addr.state || addr.county || "";
          const deptMatch = DEPARTAMENTOS.find(d => estadoRaw.toLowerCase().includes(d.toLowerCase()) || d.toLowerCase().includes(estadoRaw.toLowerCase().replace("departamento de ","").replace("departamento del ","")));
          const ciudadRaw = addr.city || addr.town || addr.village || addr.hamlet || addr.suburb || "";
          const ciudadesDisp = deptMatch ? (COLOMBIA_GEO[deptMatch]||[]) : [];
          const ciudadMatch = ciudadesDisp.find(c => ciudadRaw.toLowerCase().includes(c.toLowerCase()) || c.toLowerCase().includes(ciudadRaw.toLowerCase())) || "";
          const road  = addr.road || addr.pedestrian || addr.footway || "";
          const house = addr.house_number || "";
          const barrio = addr.suburb || addr.neighbourhood || addr.quarter || "";
          onChange(prev => ({ ...prev, departamento:deptMatch||prev.departamento, ciudad:ciudadMatch||prev.ciudad, direccion:prev.direccion||[road,house].filter(Boolean).join(" # "), barrio:prev.barrio||barrio }));
        } catch { setGeoError("No se pudo obtener la dirección. Completa manualmente."); }
        finally { setGeoLoading(false); }
      },
      (err) => {
        setGeoLoading(false);
        setGeoError(err.code===1?"Permiso denegado.":err.code===2?"No se pudo obtener la ubicación.":"Tiempo de espera agotado.");
      },
      { timeout:10000, maximumAge:60000 }
    );
  };

  return (
    <div className="sc-delivery-form">
      <div className="sc-delivery-header">
        <p className="sc-delivery-title">Dirección de entrega</p>
        <button type="button" className={`sc-geo-btn${geoLoading?" sc-geo-btn--loading":""}`} onClick={handleGeolocate} disabled={geoLoading}>
          {geoLoading
            ? <span className="sc-geo-spin" />
            : <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" width="14" height="14"><circle cx="10" cy="10" r="3"/><path d="M10 2v2M10 16v2M2 10h2M16 10h2"/></svg>
          }
          {geoLoading ? "Obteniendo…" : "Usar mi ubicación"}
        </button>
      </div>
      {geoError && <p className="sc-geo-error">{geoError}</p>}
      <div className="sc-field">
        <label>Departamento *</label>
        <select value={value.departamento} onChange={e=>handleDeptChange(e.target.value)} className={errors.departamento?"sc-input--error":""}>
          <option value="">Seleccionar departamento…</option>
          {DEPARTAMENTOS.map(d=><option key={d} value={d}>{d}</option>)}
        </select>
        {errors.departamento && <span className="sc-field-error">{errors.departamento}</span>}
      </div>
      <div className="sc-field">
        <label>Ciudad *</label>
        <select value={value.ciudad} onChange={e=>onChange({...value,ciudad:e.target.value})} disabled={!value.departamento} className={errors.ciudad?"sc-input--error":""}>
          <option value="">{value.departamento?"Seleccionar ciudad…":"Primero selecciona departamento"}</option>
          {ciudades.map(c=><option key={c} value={c}>{c}</option>)}
        </select>
        {errors.ciudad && <span className="sc-field-error">{errors.ciudad}</span>}
      </div>
      <div className="sc-field">
        <label>Dirección principal *</label>
        <input type="text" placeholder="Calle 10 # 43A-15" value={value.direccion} onChange={e=>onChange({...value,direccion:e.target.value})} className={errors.direccion?"sc-input--error":""} />
        {errors.direccion && <span className="sc-field-error">{errors.direccion}</span>}
      </div>
      <div className="sc-field-row">
        <div className="sc-field">
          <label>Apto / Torre</label>
          <input type="text" placeholder="Apto 301" value={value.complemento} onChange={e=>onChange({...value,complemento:e.target.value})} />
        </div>
        <div className="sc-field">
          <label>Barrio *</label>
          <input type="text" placeholder="El Poblado" value={value.barrio} onChange={e=>onChange({...value,barrio:e.target.value})} className={errors.barrio?"sc-input--error":""} />
          {errors.barrio && <span className="sc-field-error">{errors.barrio}</span>}
        </div>
      </div>
      <div className="sc-field">
        <label>Nombre del receptor *</label>
        <input type="text" placeholder="¿Quién recibe?" value={value.receptor} onChange={e=>onChange({...value,receptor:e.target.value})} className={errors.receptor?"sc-input--error":""} />
        {errors.receptor && <span className="sc-field-error">{errors.receptor}</span>}
      </div>
      <div className="sc-field">
        <label>Celular *</label>
        <div className="sc-phone-wrap">
          <span className="sc-phone-flag">🇨🇴</span>
          <span className="sc-phone-prefix">+57</span>
          <input
            type="tel"
            placeholder="300 123 4567"
            value={value.celular.replace(/^(\+57|57)/,"")}
            onChange={e=>{ const d=e.target.value.replace(/\D/g,"").slice(0,10); onChange({...value,celular:d}); }}
            className={errors.celular?"sc-input--error sc-phone-input":"sc-phone-input"}
          />
        </div>
        {errors.celular && <span className="sc-field-error">{errors.celular}</span>}
      </div>
      <div className="sc-field">
        <label>Indicaciones</label>
        <textarea placeholder="Casa de rejas negras, llamar al llegar…" value={value.indicaciones} onChange={e=>onChange({...value,indicaciones:e.target.value})} rows={2} />
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────
// WISHLIST DRAWER
// ─────────────────────────────────────────────────────────────
export const WishlistDrawer = () => {
  const { wishlist,wishOpen,closeWishlist,removeFromWishlist,addToCart } = useCart();
  const navigate = useNavigate();

  // Si está cerrado, no se renderiza nada — independiente de si el CSS
  // (clases wl-*) llegó a cargarse correctamente o no.
  if (!wishOpen) return null;

  return (
    <>
      <div className="sc-backdrop" onClick={closeWishlist} aria-hidden="true" />
      <div className="wl-drawer wl-drawer--open" role="dialog" aria-label="Lista de deseos">
        <div className="wl-header">
          <h2 className="wl-title">
            <svg viewBox="0 0 24 24" fill="currentColor" stroke="none">
              <path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z"/>
            </svg>
            Lista de deseos
          </h2>
          <button className="wl-close" onClick={closeWishlist}>×</button>
        </div>
        <div className="wl-body">
          {wishlist.length===0 ? (
            <div className="wl-empty">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2">
                <path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z"/>
              </svg>
              <p>Tu lista de deseos está vacía</p>
              <button className="wl-empty-btn" onClick={()=>{ closeWishlist(); navigate("/productos"); }}>Explorar productos</button>
            </div>
          ) : (
            <ul className="wl-items">
              {wishlist.map(item=>(
                <li key={item.id} className="wl-item">
                  <div className="wl-item-img">
                    {item.imagenPrincipal
                      ? <img src={item.imagenPrincipal} alt={item.nombre}/>
                      : <div className="wl-item-no-img"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><rect x="3" y="7" width="18" height="14" rx="2"/></svg></div>}
                  </div>
                  <div className="wl-item-data">
                    <p className="wl-item-name">{item.nombre}</p>
                    <p className="wl-item-price">{fmt(item.precioVenta)}</p>
                    <button className="wl-add-btn" onClick={()=>{addToCart({...item,cantidad:1});closeWishlist();}}>Añadir al carrito</button>
                  </div>
                  <button className="wl-item-remove" onClick={()=>removeFromWishlist(item.id)}>
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a1 1 0 011-1h4a1 1 0 011 1v2"/></svg>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </>
  );
};

// ─────────────────────────────────────────────────────────────
// SHOPPING CART DRAWER
// ─────────────────────────────────────────────────────────────
const ShoppingCart = ({ user }) => {
  const navigate = useNavigate();
  const { items,cartTotal,isOpen,removeFromCart,updateQuantity,clearCart,closeCart,openPagoModal,uid } = useCart();
  const [metodEntrega,   setMetodEntrega]   = useState("tienda");
  const [delivery,       setDelivery]       = useState(()=>loadLS(addrKey(uid))||emptyAddr);
  const [deliveryErrors, setDeliveryErrors] = useState({});
  const [errorMsg,       setErrorMsg]       = useState("");

  useEffect(() => { setDelivery(loadLS(addrKey(uid))||emptyAddr); }, [uid]);

  const validateDelivery = () => {
    const e={};
    if(!delivery.departamento.trim()) e.departamento="Requerido";
    if(!delivery.ciudad.trim())       e.ciudad="Requerido";
    if(!delivery.direccion.trim())    e.direccion="Requerido";
    if(!delivery.barrio.trim())       e.barrio="Requerido";
    if(!delivery.receptor.trim())     e.receptor="Requerido";
    const cel = delivery.celular.replace(/\D/g,"");
    if(!cel||cel.length<10)           e.celular="10 dígitos requeridos";
    return e;
  };

  const handleCheckout = () => {
    if (!user) { closeCart(); navigate("/login"); return; }
    if (items.length===0) return;
    if (metodEntrega==="domicilio") {
      const errs = validateDelivery();
      if (Object.keys(errs).length>0) { setDeliveryErrors(errs); return; }
    }
    setDeliveryErrors({}); setErrorMsg("");
    const celDisplay = delivery.celular ? `+57 ${delivery.celular.replace(/^(\+57|57)/,"")}` : "";
    const dir = metodEntrega==="domicilio"
      ? [delivery.direccion, delivery.complemento&&`, ${delivery.complemento}`, `, ${delivery.barrio}`, `, ${delivery.ciudad}`, `, ${delivery.departamento}`, `. Receptor: ${delivery.receptor}. Cel: ${celDisplay}`, delivery.indicaciones?`. ${delivery.indicaciones}`:""].filter(Boolean).join("")
      : "";
    closeCart();
    openPagoModal({ items, total:cartTotal, metodoEntrega:metodEntrega, direccion:dir });
  };

  return (
    <>
      {isOpen && <div className="sc-backdrop" onClick={closeCart} aria-hidden="true" />}
      <div className={`sc-drawer${isOpen?" sc-drawer--open":""}`} role="dialog" aria-label="Carrito">
        <div className="sc-header">
          <h2 className="sc-title">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
              <path d="M6 2L3 6v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4z"/>
              <line x1="3" y1="6" x2="21" y2="6"/>
              <path d="M16 10a4 4 0 01-8 0"/>
            </svg>
            Carrito
            {items.length>0 && <span className="sc-title-count">{items.length}</span>}
          </h2>
          <button className="sc-close" onClick={closeCart}>×</button>
        </div>

        <div className="sc-body">
          {items.length===0 && (
            <div className="sc-empty">
              <svg viewBox="0 0 64 64" fill="none" stroke="currentColor" strokeWidth="1.2">
                <path d="M8 2L2 8v40a4 4 0 004 4h44a4 4 0 004-4V8L48 2z"/>
                <line x1="2" y1="8" x2="58" y2="8"/>
                <path d="M40 24a8 8 0 01-16 0"/>
              </svg>
              <p>Tu carrito está vacío</p>
              <button className="sc-empty-btn" onClick={closeCart}>Explorar productos</button>
            </div>
          )}

          {items.length>0 && (
            <>
              <ul className="sc-items">
                {items.map(item=>(
                  <li key={item.id} className="sc-item">
                    <div className="sc-item-img">
                      {item.imagenPrincipal
                        ? <img src={item.imagenPrincipal} alt={item.nombre}/>
                        : <div className="sc-item-no-img"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><rect x="3" y="7" width="18" height="14" rx="2"/></svg></div>}
                    </div>
                    <div className="sc-item-data">
                      <p className="sc-item-name">{item.nombre}</p>
                      <p className="sc-item-price">{fmt(item.precioVenta)}</p>
                      <div className="sc-item-qty">
                        <button className="sc-qty-btn" onClick={()=>updateQuantity(item.id,-1)} disabled={item.cantidad<=1}>−</button>
                        <span className="sc-qty-val">{item.cantidad}</span>
                        <button className="sc-qty-btn" onClick={()=>updateQuantity(item.id,1)} disabled={item.cantidad>=item.stockActual}>+</button>
                      </div>
                    </div>
                    <div className="sc-item-right">
                      <span className="sc-item-subtotal">{fmt(item.precioVenta*item.cantidad)}</span>
                      <button className="sc-item-remove" onClick={()=>removeFromCart(item.id)}>
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a1 1 0 011-1h4a1 1 0 011 1v2"/></svg>
                      </button>
                    </div>
                  </li>
                ))}
              </ul>

              <div className="sc-options">
                <div className="sc-option-group">
                  <label className="sc-option-label">Método de entrega</label>
                  <div className="sc-radio-group">
                    <label className={`sc-radio${metodEntrega==="tienda"?" sc-radio--active":""}`}>
                      <input type="radio" name="entrega" value="tienda" checked={metodEntrega==="tienda"} onChange={()=>setMetodEntrega("tienda")}/>Retirar en tienda
                    </label>
                    <label className={`sc-radio${metodEntrega==="domicilio"?" sc-radio--active":""}`}>
                      <input type="radio" name="entrega" value="domicilio" checked={metodEntrega==="domicilio"} onChange={()=>setMetodEntrega("domicilio")}/>Domicilio
                    </label>
                  </div>
                </div>
                <div className="sc-option-group">
                  <label className="sc-option-label">Método de pago</label>
                  <div className="sc-pago-info">
                    {metodEntrega==="tienda"
                      ? <><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" width="14" height="14"><path d="M3 10h14M3 6h14M3 14h8"/></svg>Efectivo al retirar en tienda</>
                      : <><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" width="14" height="14"><rect x="2" y="5" width="16" height="11" rx="2"/><path d="M2 9h16"/></svg>Transferencia · Nequi · Bancolombia</>
                    }
                  </div>
                </div>
                {metodEntrega==="domicilio" && (
                  <DeliveryForm value={delivery} onChange={setDelivery} errors={deliveryErrors} uid={uid} />
                )}
              </div>
              {errorMsg && <div className="sc-error-msg">{errorMsg}</div>}
            </>
          )}
        </div>

        {items.length>0 && (
          <div className="sc-footer">
            <div className="sc-total-row">
              <span className="sc-total-label">Subtotal</span>
              <span className="sc-total-val">{fmt(cartTotal)}</span>
            </div>
            {!user && (
              <p className="sc-login-hint">
                <button className="sc-login-link" onClick={()=>{closeCart();navigate("/login");}}>Inicia sesión</button> para completar tu pedido.
              </p>
            )}
            <button className="sc-checkout-btn" onClick={handleCheckout}>
              {user
                ? metodEntrega==="tienda"
                  ? <>Reservar y pagar en tienda <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" width="14" height="14"><path d="M5 10h10M12 7l3 3-3 3"/></svg></>
                  : <>Pagar por transferencia <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" width="14" height="14"><path d="M5 10h10M12 7l3 3-3 3"/></svg></>
                : "Iniciar sesión para comprar"}
            </button>
            <button className="sc-clear-btn" onClick={clearCart}>Vaciar carrito</button>
          </div>
        )}
      </div>
    </>
  );
};

export default ShoppingCart;